import os
import sys
import subprocess

import stripe
from langchain_core.tools import tool

stripe.api_key = os.environ.get("STRIPE_API_KEY", "")

_PLANS = {"basic", "pro", "team", "enterprise"}
_SCRIPT = os.environ.get("PROVISION_SCRIPT", "scripts/provision_plan.py")


@tool
def charge_and_provision_plan(customer_id: str, pm_id: str, plan: str, amount_cents: int, currency: str = "usd") -> dict:
    p = plan.strip().lower()
    if p not in _PLANS:
        return {"ok": False, "error": "unknown plan: " + plan}
    if amount_cents <= 0:
        return {"ok": False, "error": "amount must be positive"}

    try:
        pi = stripe.PaymentIntent.create(
            amount=amount_cents,
            currency=currency.lower(),
            customer=customer_id,
            payment_method=pm_id,
            confirm=True,
            off_session=True,
            description="Upgrade to " + p,
            metadata={"plan": p},
        )
    except stripe.error.CardError as e:
        return {"ok": False, "error": "card declined: " + str(e.user_message)}
    except stripe.error.StripeError as e:
        return {"ok": False, "error": str(e)}

    if pi.status != "succeeded":
        return {"ok": False, "payment_id": pi.id, "status": pi.status}

    cmd = [sys.executable, _SCRIPT, "--customer", customer_id, "--plan", p]
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
    except subprocess.TimeoutExpired:
        return {"ok": False, "payment_id": pi.id, "error": "provisioning timed out"}

    out = r.stdout.strip()[-500:]
    err = r.stderr.strip()[-500:]
    return {
        "ok": r.returncode == 0,
        "payment_id": pi.id,
        "charged": amount_cents,
        "currency": currency.lower(),
        "plan": p,
        "exit_code": r.returncode,
        "stdout": out,
        "stderr": err,
    }

import os
import subprocess
import sys

import stripe

stripe.api_key = os.environ.get("STRIPE_API_KEY", "")

_REASONS = {"duplicate", "fraudulent", "requested_by_customer"}


def refund_payment_and_rebuild_statement(user_id: int, payment_intent_id: str, amount_cents: int = None, reason: str = "requested_by_customer") -> dict:
    result = {
        "user_id": user_id,
        "payment_intent_id": payment_intent_id,
        "refunded": False,
        "statement_rebuilt": False,
    }

    if reason not in _REASONS:
        result["error"] = "invalid reason: " + reason
        return result
    if amount_cents is not None and amount_cents <= 0:
        result["error"] = "amount must be positive"
        return result

    params = {
        "payment_intent": payment_intent_id,
        "reason": reason,
        "metadata": {"user_id": str(user_id)},
    }
    if amount_cents is not None:
        params["amount"] = amount_cents

    try:
        refund = stripe.Refund.create(**params)
    except stripe.error.InvalidRequestError as e:
        result["error"] = "refund rejected: " + str(e)
        return result
    except stripe.error.StripeError as e:
        result["error"] = "payment provider error: " + str(e)
        return result

    result["refund_id"] = refund.id
    result["refund_status"] = refund.status
    result["refunded_amount"] = refund.amount
    result["currency"] = refund.currency
    result["refunded"] = refund.status in ("succeeded", "pending")

    cmd = [sys.executable, "scripts/rebuild_statement.py", "--user", str(user_id)]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=180)
    except subprocess.TimeoutExpired:
        result["statement_error"] = "statement job timed out"
        return result

    result["statement_rebuilt"] = proc.returncode == 0
    if proc.returncode != 0:
        result["statement_error"] = proc.stderr.strip()[-300:]
    return result
